// One sound from listen.txt: its file, its name and what it is
class ListenClip
{
    public string FileName { get; set; }      // file name, no ending
    public string Name { get; set; }          // the name, like Curlew
    public string InSentence { get; set; }    // like "the curlew"
    public string Explanation { get; set; }   // what made the sound

    // Makes one ListenClip from a line of listen.txt, split at each |
    public ListenClip(string[] parts)
    {
        FileName = parts[0];
        Name = parts[1];
        InSentence = parts[2];
        Explanation = parts[3];
    }

    // Reads every sound in listen.txt into a list
    public static List<ListenClip> LoadAll()
    {
        List<ListenClip> clips = new List<ListenClip>();
        string path = Files.Data("listen.txt");
        if (!File.Exists(path)) return clips;   // no file: an empty list
        StreamReader reader = new StreamReader(path);
        while (!reader.EndOfStream)
        {
            string line = reader.ReadLine();
            string[] parts = line.Split('|');
            if (parts.Length != 4) continue;    // skip a broken line
            clips.Add(new ListenClip(parts));
        }
        reader.Close();
        return clips;
    }

// ---------- the game-form methods from chapter 9 ----------

// Keeps the result on the map, even if the window is then closed
private void KeepResult()
{
    Expedition.Finish(gameNumber, result);
    finished = true;
    lblScore.Text = "Points: " + result.Score;
}

// Fills in the Round over panel and brings it to the front
private void ShowRoundOver()
{
    lblRoundScore.Text = "You scored " + result.Score
        + " out of 100 points.";
    lblWellList.Text = ListText(result.WentWell,
        "thing that went well", "things that went well");
    lblWrongList.Text = ListText(result.WentWrong,
        "thing that went wrong", "things that went wrong");
    if (result.Score >= 60) Sound.Play("win.wav");
    else Sound.Play("lose.wav");
    pnlRoundOver.Visible = true;
    pnlRoundOver.BringToFront();
}

// Up to 3 lines from a list, then how many more there are
private string ListText(List<string> lines, string one, string many)
{
    if (lines.Count == 0) return "Nothing this time.";
    string text = "";
    for (int i = 0; i < lines.Count && i < 3; i++)
    {
        text = text + "- " + lines[i] + Environment.NewLine;
    }
    int more = lines.Count - 3;
    if (more == 1) text = text + "And 1 more " + one + ".";
    if (more > 1) text = text + "And " + more + " more " + many + ".";
    return text;
}

// Back to the map: closing the window runs FormClosing
private void btnBack_Click(object sender, EventArgs e)
{
    this.Close();
}

// The Round over panel's Back to the map button
private void btnDone_Click(object sender, EventArgs e)
{
    this.Close();
}

// Runs as the window closes, by Back, by Done or by the X
private void frmListen_FormClosing(object sender,
    FormClosingEventArgs e)
{
    if (finished) return;    // a finished round closes at once
    DialogResult answer = MessageBox.Show("Leave Listen Out? It will "
        + "score nothing, but you can come back and climb it again.",
        "Summit Ready", MessageBoxButtons.YesNo);
    if (answer == DialogResult.No) e.Cancel = true;   // stay
}

// Shows the speaker picture that matches the sound being on or off
private void ShowSpeaker()
{
    string icon = "icon-speaker-on-64.png";
    if (Sound.Muted) icon = "icon-speaker-muted-64.png";
    picSound.Image = Files.Picture("Icons", icon);
}

// The speaker picture turns the sound off, or back on
private void picSound_Click(object sender, EventArgs e)
{
    Sound.Muted = !Sound.Muted;
    ShowSpeaker();
}

// ---------- Listen Out ----------
private List<ListenClip> clips;        // every sound in listen.txt
private int[] order;                   // the sounds, mixed up
private int number = 0;                // this sound, 0 to 9
private int playsLeft = 3;             // plays left for this sound
private bool answered = false;         // true once a picture is picked
private Button[] picks;                // the four answer buttons
private int[] clipOf = new int[4];     // the sound on each button
private int right = 0;                 // right answers so far
private Random random = new Random();
private List<string> wellLines = new List<string>();
private List<string> wrongLines = new List<string>();

// The sentence under Play the sound, for left plays still to go
private string PlaysText(int left)
{
    if (left == 3)
        return "Play the sound first. You can play it 3 times.";
    if (left == 2) return "You can play this sound 2 more times.";
    if (left == 1) return "You can play this sound 1 more time.";
    return "You have played this sound three times.";
}

// Picks the right sound plus 3 others, with no repeats
private List<int> PickChoices(int answer)
{
    List<int> choices = new List<int>();
    choices.Add(answer);
    string name = clips[answer].FileName;
    if (name == "whistle-six") choices.Add(FindClip("whistle-three"));
    if (name == "whistle-three") choices.Add(FindClip("whistle-six"));
    while (choices.Count < 4)
    {
        int n = random.Next(clips.Count);
        if (!choices.Contains(n)) choices.Add(n);
    }
    return choices;
}

// The place in the list of the sound called fileName
private int FindClip(string fileName)
{
    for (int i = 0; i < clips.Count; i++)
    {
        if (clips[i].FileName == fileName) return i;
    }
    return 0;   // not found: any sound will do
}

// Puts the next sound's four pictures on the buttons
private void ShowSound()
{
    int answer = order[number];
    List<int> choices = PickChoices(answer);
    int[] mixed = Mix.ShuffledNumbers(4);
    for (int i = 0; i < 4; i++)
    {
        clipOf[i] = choices[mixed[i]];
        ListenClip c = clips[clipOf[i]];
        Image photo = Files.Picture("Listen", c.FileName + ".jpg");
        if (photo != null) picks[i].Image = new Bitmap(photo, 210, 180);
        picks[i].Text = c.Name;
        picks[i].BackColor = Color.White;
        picks[i].ForeColor = Color.FromArgb(38, 50, 56);
        picks[i].Cursor = Cursors.Hand;
        picks[i].Enabled = false;   // listen before you guess
    }

    playsLeft = 3;
    answered = false;
    lblRound.Text = "Sound " + (number + 1) + " of 10";
    lblPlays.Text = PlaysText(playsLeft);
    lblExplain.Text = "";
    btnPlay.Enabled = true;
    btnPlay.BackColor = Color.FromArgb(242, 183, 5);
    btnNext.Visible = false;
}

private void frmListen_Load(object sender, EventArgs e)
{
    // Runs once, right before the window first appears
    ShowSpeaker();
    picks = new Button[] { btnPick1, btnPick2, btnPick3, btnPick4 };
    btnPlay.Image = Files.Picture("Icons", "icon-speaker-on-64.png");
    clips = ListenClip.LoadAll();
    if (clips.Count < 10)
    {
        lblPlays.Text = "Listen Out needs 10 sounds in "
            + "Data\\listen.txt, each with 4 parts.";
        btnPlay.Enabled = false;
        return;
    }
    order = Mix.ShuffledNumbers(clips.Count);
    ShowSound();
}

// Play the sound: up to three times, then the button switches off
private void btnPlay_Click(object sender, EventArgs e)
{
    if (playsLeft == 0) return;
    Sound.Play(clips[order[number]].FileName + ".wav");
    playsLeft--;
    lblPlays.Text = PlaysText(playsLeft);
    if (playsLeft == 0)
    {
        btnPlay.Enabled = false;
        // A flat button looks the same when off, so grey it
        btnPlay.BackColor = Color.FromArgb(207, 216, 220);
    }
    if (!answered)
    {
        for (int i = 0; i < 4; i++)
        {
            picks[i].Enabled = true;
        }
    }
}

// One of the four pictures was clicked
private void Pick_Click(object sender, EventArgs e)
{
    if (answered) return;          // this sound is done already
    for (int i = 0; i < 4; i++)
    {
        if (sender == picks[i]) Answer(i);
    }
}

// Marks the picture on button picked
private void Answer(int picked)
{
    answered = true;
    int answer = order[number];
    ListenClip clip = clips[answer];
    for (int i = 0; i < 4; i++)
    {
        picks[i].Cursor = Cursors.Default;
        if (clipOf[i] == answer)
        {
            picks[i].BackColor = Color.FromArgb(62, 142, 65);
            picks[i].ForeColor = Color.White;
        }
        else if (i == picked)
        {
            picks[i].BackColor = Color.FromArgb(178, 58, 46);
            picks[i].ForeColor = Color.White;
        }
    }

    if (clipOf[picked] == answer)
    {
        right++;
        lblExplain.Text = "Correct. " + clip.Explanation;
        wellLines.Add("You recognised " + clip.InSentence + ".");
        Sound.Play("correct.wav");
    }
    else
    {
        lblExplain.Text = "Not quite. It was " + clip.InSentence
            + ". " + clip.Explanation;
        wrongLines.Add(MissLine(clip, clips[clipOf[picked]]));
        Sound.Play("wrong.wav");
    }
    lblScore.Text = "Points: " + right * 10;
    if (number == 9)
    {
        btnNext.Text = "See my score";
        RecordResult();
    }
    btnNext.Visible = true;
}

// The What went wrong line for a missed sound
private string MissLine(ListenClip clip, ListenClip picked)
{
    bool whistles = clip.FileName.StartsWith("whistle")
        && picked.FileName.StartsWith("whistle");
    if (whistles && clip.FileName == "whistle-six")
    {
        return "You mixed up the whistles. Six blasts means "
            + "\"I need help\".";
    }
    if (whistles)
    {
        return "You mixed up the whistles. Three blasts means "
            + "\"We hear you, help is coming\".";
    }
    return "You did not recognise " + clip.InSentence + ".";
}

// Next sound, or See my score after sound 10
private void btnNext_Click(object sender, EventArgs e)
{
    if (number == 9)
    {
        ShowRoundOver();
        return;
    }
    number++;
    ShowSound();
}

// Works out the score, adds the feedback, then keeps the result
private void RecordResult()
{
    int score = right * 10;
    result = new GameResult("Listen Out", score);
    result.WentWell.AddRange(wellLines);
    result.WentWrong.AddRange(wrongLines);
    KeepResult();
}

